Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='setupagentguided', at=datetime(2026, 10, 7, 0, 0, 0), actor='owner', title='Setup is guided by an agent; no page asks for a raw configuration field', body='Connecting an account, a calendar or a source is a setup conversation that applies a template and reads it back from the instance file. Settings shows what is connected and its health. A secret is typed only into a one-time card, never into a form field the page keeps.', rationale='The app is meant to be set up by people other than its author.', supersedes=()))